messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>3D Treadmill Animation</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #1a1a2e; overflow: hidden; }
canvas { display: block; width: 100vw; height: 100vh; }
</style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// ─── Scene Setup ───
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.FogExp2(0x1a1a2e, 0.015);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 3, 8);
camera.lookAt(0, 1.5, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// ─── Lighting ───
const ambientLight = new THREE.AmbientLight(0x888899, 0.5);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(3, 5, 3);
dirLight.castShadow = true;
scene.add(dirLight);

const hemiLight = new THREE.HemisphereLight(0x4488ff, 0x1a1a2e, 0.5);
scene.add(hemiLight);

// ─── Treadmill Ground ───
const groundGeometry = new THREE.PlaneGeometry(12, 12, 8, 8);
const groundMaterial = new THREE.MeshBasicMaterial({
  color: 0x333333,
  flatShading: true,
  transparent: true,
  opacity: 0.95
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.1;
ground.receiveShadow = true;
ground.userData = { moving: true, speed: 0 };
scene.add(ground);

// ─── Character Construction (Procedural) ───
const CHAR_COLOR = 0x6644aa;
const CHAR_BONE_COLOR = 0x9988ff;
const CHAR_BONE_THICK = 0.12;

const buildChar = () => {
  const charGroup = new THREE.Group();

  // ── Head ──
  const headGeo = new THREE.SphereGeometry(0.22, 16, 16);
  const headMat = new THREE.MeshBasicMaterial({ color: CHAR_COLOR });
  const head = new THREE.Mesh(headGeo, headMat);
  head.position.set(0, 1.7, 0);
  charGroup.add(head);

  // ── Torso ──
  const torsoGeo = new THREE.CylinderGeometry(0.28, 0.32, 0.55, 16);
  const torsoMat = new THREE.MeshBasicMaterial({ color: CHAR_COLOR });
  const torso = new THREE.Mesh(torsoGeo, torsoMat);
  torso.position.set(0, 1.3, 0);
  charGroup.add(torso);

  // ── Legs (each) ──
  const createLeg = (side) => {
    const legGroup = new THREE.Group();
    const thighGeo = new THREE.CylinderGeometry(0.06, 0.07, 0.4, 8);
    const thighMat = new THREE.MeshBasicMaterial({ color: CHAR_COLOR });
    const thigh = new THREE.Mesh(thighGeo, thighMat);
    thigh.position.set(side * 0.08, 1.05, 0);
    legGroup.add(thigh);

    const shinGeo = new THREE.CylinderGeometry(0.05, 0.055, 0.35, 8);
    const shinMat = new THREE.MeshBasicMaterial({ color: CHAR_COLOR });
    const shin = new THREE.Mesh(shinGeo, shinMat);
    shin.position.set(side * 0.08, 0.65, 0);
    legGroup.add(shin);

    const footGeo = new THREE.CylinderGeometry(0.07, 0.08, 0.06, 8);
    const footMat = new THREE.MeshBasicMaterial({ color: 0x8877aa });
    const foot = new THREE.Mesh(footGeo, footMat);
    foot.position.set(side * 0.1, 0.3, 0);
    legGroup.add(foot);

    // Bone lines (visible during movement)
    const boneMat = new THREE.LineBasicMaterial({ color: CHAR_BONE_COLOR, transparent: true, opacity: 0.4 });
    const boneGeo = new THREE.LineGeometry(0.4);
    const bone = new THREE.Line(boneGeo, boneMat);
    bone.position.set(side * 0.08, 0.82, 0);
    bone.rotation.x = Math.PI / 2;
    legGroup.add(bone);

    return legGroup;
  };

  const leftLeg = createLeg(-1);
  const rightLeg = createLeg(1);
  charGroup.add(leftLeg);
  charGroup.add(rightLeg);

  // ── Arms (each) ──
  const createArm = (side) => {
    const armGroup = new THREE.Group();
    const upperGeo = new THREE.CylinderGeometry(0.04, 0.045, 0.35, 8);
    const upperMat = new THREE.MeshBasicMaterial({ color: CHAR_COLOR });
    const upper = new THREE.Mesh(upperGeo, upperMat);
    upper.position.set(side * 0.35, 1.4, 0);
    armGroup.add(upper);

    const forearmGeo = new THREE.CylinderGeometry(0.035, 0.04, 0.3, 8);
    const forearmMat = new THREE.MeshBasicMaterial({ color: CHAR_COLOR });
    const forearm = new THREE.Mesh(forarmGeo, forearmMat);
    forearm.position.set(side * 0.35, 1.05, 0);
    armGroup.add(forearm);

    const handGeo = new THREE.CylinderGeometry(0.04, 0.045, 0.04, 8);
    const handMat = new THREE.MeshBasicMaterial({ color: 0x9977aa });
    const hand = new THREE.Mesh(handGeo, handMat);
    hand.position.set(side * 0.35, 0.75, 0);
    armGroup.add(hand);

    const boneMat = new THREE.LineBasicMaterial({ color: CHAR_BONE_COLOR, transparent: true, opacity: 0.4 });
    const boneGeo = new THREE.LineGeometry(0.35);
    const bone = new THREE.Line(boneGeo, boneMat);
    bone.position.set(side * 0.35, 1.18, 0);
    bone.rotation.x = Math.PI / 2;
    armGroup.add(bone);

    return armGroup;
  };

  const leftArm = createArm(-1);
  const rightArm = createArm(1);
  charGroup.add(leftArm);
  charGroup.add(rightArm);

  return charGroup;
};

const char = buildChar();
scene.add(char);

// ─── Limb Groups for Animation ───
// Each limb is a Group with a bone child for rotation reference
const leftLeg = char.children[0];
const rightLeg = char.children[1];
const leftArm = char.children[2];
const rightArm = char.children[3];

// ─── Animation State ───
const STATE_STAND = 0;
const STATE_WALK = 1;
const STATE_RUN = 2;
const STATE_STAND2 = 3;

const state = {
  current: STATE_STAND,
  elapsed: 0,
  total: 10,
  phase: {
    stand1: 2,
    walk: 3,
    run: 3,
    stand2: 2
  },
  currentPhase: 0,
  phaseElapsed: 0,
  walkPhase: 0,
  runPhase: 0,
  walkSpeed: 0.08,
  runSpeed: 0.15
};

// ─── Limb Angle Functions ───
// Returns angle in radians for a given time and state
function getLegAngle(t, state, side) {
  if (state === STATE_STAND || state === STATE_STAND2) {
    return 0;
  }
  const phase = state === STATE_WALK ? state.walkPhase : state.runPhase;
  const freq = state === STATE_WALK ? 1.5 : 2.5;
  const amp = state === STATE_WALK ? 0.35 : 0.55;
  const phaseShift = side * 0.5;
  const angle = Math.sin(phase * freq * Math.PI * 2 + phaseShift) * amp;
  return angle;
}

function getArmAngle(t, state, side) {
  if (state === STATE_STAND || state === STATE_STAND2) {
    return 0;
  }
  const phase = state === STATE_WALK ? state.walkPhase : state.runPhase;
  const freq = state === STATE_WALK ? 1.5 : 2.5;
  const amp = state === STATE_WALK ? 0.25 : 0.45;
  const phaseShift = side * 0.5;
  const angle = Math.sin(phase * freq * Math.PI * 2 + phaseShift) * amp;
  return angle;
}

function getTorsoLean(t, state) {
  if (state === STATE_STAND || state === STATE_STAND2) {
    return 0;
  }
  if (state === STATE_RUN) {
    return 0.15;
  }
  return 0;
}

function getGroundOffset(t, state) {
  if (state === STATE_RUN) {
    return 0.3 * Math.sin(t * 10);
  }
  return 0;
}

// ─── Animation Loop ───
const clock = new THREE.Clock();
let lastTime = 0;

function animate(timestamp) {
  requestAnimationFrame(animate);

  const dt = Math.min((timestamp - lastTime) / 1000, 0.1);
  lastTime = timestamp;

  // ── Update State ──
  state.elapsed += dt;
  const cycleLen = state.phase.stand1 + state.phase.walk + state.phase.run + state.phase.stand2;

  if (state.phaseElapsed >= state.phase.stand1) {
    state.phaseElapsed -= state.phase.stand1;
    state.current = STATE_WALK;
    state.walkPhase = 0;
  } else {
    state.phaseElapsed += dt;
    state.current = STATE_STAND;
  }

  if (state.phaseElapsed >= state.phase.walk) {
    state.phaseElapsed -= state.phase.walk;
    state.current = STATE_RUN;
    state.runPhase = 0;
  } else {
    state.phaseElapsed += dt;
    state.walkPhase += dt * state.walkSpeed;
  }

  if (state.phaseElapsed >= state.phase.run) {
    state.phaseElapsed -= state.phase.run;
    state.current = STATE_STAND2;
    state.runPhase = 0;
  } else {
    state.phaseElapsed += dt;
    state.runPhase += dt * state.runSpeed;
  }

  if (state.phaseElapsed >= cycleLen) {
    state.phaseElapsed -= cycleLen;
    state.current = STATE_STAND;
    state.walkPhase = 0;
    state.runPhase = 0;
  }

  // ── Update Character ──
  const t = state.elapsed;

  // Torso lean
  const lean = getTorsoLean(t, state);
  char.rotation.z = lean;

  // Left leg
  const leftAngle = getLegAngle(t, state, -1);
  leftLeg.rotation.z = leftAngle;
  leftLeg.rotation.x = Math.sin(leftAngle * 0.5) * 0.1;

  // Right leg
  const rightAngle = getLegAngle(t, state, 1);
  rightLeg.rotation.z = rightAngle;
  rightLeg.rotation.x = Math.sin(rightAngle * 0.5) * 0.1;

  // Left arm
  const leftArmAngle = getArmAngle(t, state, -1);
  leftArm.rotation.z = leftArmAngle;
  leftArm.rotation.x = Math.sin(leftArmAngle * 0.3) * 0.05;

  // Right arm
  const rightArmAngle = getArmAngle(t, state, 1);
  rightArm.rotation.z = rightArmAngle;
  rightArm.rotation.x = Math.sin(rightArmAngle * 0.3) * 0.05;

  // ── Update Treadmill ──
  const groundSpeed = state.current === STATE_WALK ? 0.5 : (state.current === STATE_RUN ? 1.0 : 0);
  ground.userData.speed = groundSpeed;
  if (ground.userData.speed > 0) {
    ground.position.z -= ground.userData.speed * dt;
  }

  // ── Render ──
  renderer.render(scene, camera);
}

// ─── Resize Handler ──
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ── Start ──
animate(0);
</script>
</body>
</html>
```
